--
-- Name: v_bi_canh_bao; Type: VIEW; Schema: gold; Owner: -
--

CREATE VIEW gold.v_bi_canh_bao AS
 SELECT p.code AS ky,
    u.code AS ma_don_vi,
    u.name AS ten_don_vi,
    r.name AS dia_ban,
    a.alert_type AS loai,
    a.severity AS muc_do,
    a.message AS noi_dung
   FROM (((gold.alerts a
     JOIN public.periods p ON ((p.id = a.period_id)))
     JOIN public.units u ON ((u.id = a.unit_id)))
     JOIN public.regions r ON ((r.id = u.region_id)));


--
-- Name: v_bi_dia_ban; Type: VIEW; Schema: gold; Owner: -
--

CREATE VIEW gold.v_bi_dia_ban AS
 SELECT p.code AS ky,
    r.code AS ma_dia_ban,
    r.name AS dia_ban,
    r.type AS loai,
    rs.avg_score AS dti_tb,
    rs.admin_avg AS dti_hanh_chinh,
    rs.edu_avg AS dti_giao_duc,
    rs.unit_count AS so_don_vi,
    rs.rank AS hang
   FROM ((gold.region_scores rs
     JOIN public.periods p ON ((p.id = rs.period_id)))
     JOIN public.regions r ON ((r.id = rs.region_id)));


--
-- Name: v_bi_dti; Type: VIEW; Schema: gold; Owner: -
