--
-- Name: v_bi_nhiem_vu; Type: VIEW; Schema: gold; Owner: -
--

CREATE VIEW gold.v_bi_nhiem_vu AS
 SELECT t.code AS ma_nhiem_vu,
    t.title AS trich_yeu,
    ua.name AS co_quan_giao,
    u.name AS don_vi_thuc_hien,
    r.name AS dia_ban,
    t.deadline AS han,
    a.status AS trang_thai,
    a.progress AS tien_do,
    (((a.status)::text <> ALL ((ARRAY['hoan_thanh'::character varying, 'khong_tiep_nhan'::character varying])::text[])) AND (t.deadline < CURRENT_DATE)) AS qua_han
   FROM ((((public.task_assignments a
     JOIN public.tasks t ON ((t.id = a.task_id)))
     JOIN public.units u ON ((u.id = a.unit_id)))
     JOIN public.units ua ON ((ua.id = t.assigner_unit_id)))
     JOIN public.regions r ON ((r.id = u.region_id)));


